css:
body {
 background: #333;
}
 #loader-8 {
  width: 75px;
  aspect-ratio: 1;
  display: grid;
  background: darkgray;
}
#loader-8::before,
#loader-8::after {
  content: '';
  grid-area: 1/1;
  width: 35px;
  aspect-ratio: 1;
  box-shadow: 0 0 0 3px #fff inset;
  filter: drop-shadow(40px 40px 0 #fff);
  animation: l8 2s infinite alternate;
}
#loader-8::after {
  margin: 0 0 0 auto;
  filter: drop-shadow(-40px 40px 0 #fff);
  animation-delay: -1s;
}
@keyframes l8 {
  0%, 10% {border-radius: 0}
  30%, 40% {border-radius: 50% 0}
  60%, 70% {border-radius: 50%}
  90%, 100% {border-radius: 0 50%}
}
